{
  "claims": [
    {
      "kind": "qualitative",
      "text": "Community Health Systems is one of the nation’s largest healthcare companies; its affiliates are leading providers of healthcare services, developing and operating healthcare delivery systems in 36 distinct markets across 14 states.",
      "citations": [
        {
          "chunk_id": "CYH-000119312526059509-0005",
          "quote": "We are one of the nation’s largest healthcare companies. Our affiliates are leading providers of healthcare services, developing and operating healthcare delivery systems in 36 distinct markets across 14 states."
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "At December 31, 2025, the company’s subsidiaries own or lease 69 affiliated hospitals with more than 10,000 beds and operate more than 1,000 sites of care.",
      "citations": [
        {
          "chunk_id": "CYH-000119312526059509-0005",
          "quote": "At December 31, 2025, our subsidiaries own or lease 69 affiliated hospitals, with more than 10,000 beds, and operate more than 1,000 sites of care"
        }
      ]
    },
    {
      "kind": "quantitative",
      "text": "Revenue was {{m:revenue:FY0}} and EBITDA was {{m:ebitda:FY0}} in {{p:FY0}}; for {{p:LTM}}, revenue was {{m:revenue:LTM}} and EBITDA was {{m:ebitda:LTM}}.",
      "citations": []
    },
    {
      "kind": "qualitative",
      "text": "Services provided through its hospitals and outpatient facilities include general acute care, emergency room, general and specialty surgery, critical care, internal medicine, obstetrics, diagnostic, psychiatric and rehabilitation services.",
      "citations": [
        {
          "chunk_id": "CYH-000119312526059509-0005",
          "quote": "Services provided through our hospitals and outpatient facilities include general acute care, emergency room, general and specialty surgery, critical care, internal medicine, obstetrics, diagnostic, psychiatric and rehabilitation services."
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "The company is paid for its services by governmental agencies, private insurers and directly by the patients it serves.",
      "citations": [
        {
          "chunk_id": "CYH-000119312526059509-0005",
          "quote": "we are paid for our services by governmental agencies, private insurers and directly by the patients we serve."
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "Labor costs have increased, and state-mandated nurse-staffing ratios or other measures to regulate staffing could significantly affect labor costs and have an adverse impact on net operating revenues.",
      "citations": [
        {
          "chunk_id": "CYH-000119312526059509-0126",
          "quote": "our hospitals and other healthcare facilities, like many other healthcare providers, have experienced increased labor costs."
        },
        {
          "chunk_id": "CYH-000119312526059509-0126",
          "quote": "State-mandated nurse-staffing ratios or other measures to regulate staffing could significantly affect labor costs and have an adverse impact on our net operating revenues"
        }
      ]
    }
  ]
}

{
  "claims": [
    {
      "kind": "quantitative",
      "text": "Debt / EBITDA was {{m:debt_to_ebitda:FY-2}} in {{p:FY-2}}, {{m:debt_to_ebitda:FY-1}} in {{p:FY-1}}, {{m:debt_to_ebitda:FY0}} in {{p:FY0}} and {{m:debt_to_ebitda:LTM}} in {{p:LTM}}, an improving trend.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "Net leverage was {{m:net_leverage:FY-2}} in {{p:FY-2}}, {{m:net_leverage:FY-1}} in {{p:FY-1}}, {{m:net_leverage:FY0}} in {{p:FY0}} and {{m:net_leverage:LTM}} in {{p:LTM}}, also improving.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "EBITDA / interest improved from {{m:interest_coverage:FY-2}} in {{p:FY-2}} and {{m:interest_coverage:FY-1}} in {{p:FY-1}} to {{m:interest_coverage:FY0}} in {{p:FY0}} and {{m:interest_coverage:LTM}} in {{p:LTM}}.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "FCF / debt was {{m:fcf_to_debt:FY-2}} in {{p:FY-2}}, {{m:fcf_to_debt:FY-1}} in {{p:FY-1}}, {{m:fcf_to_debt:FY0}} in {{p:FY0}} and {{m:fcf_to_debt:LTM}} in {{p:LTM}}, a broadly stable trend.",
      "citations": []
    },
    {
      "kind": "qualitative",
      "text": "The improvement in EBITDA / interest and leverage was supported by a higher income from operations margin and a net gain on sale of businesses in {{p:FY0}}, compared with a loss in the prior year.",
      "citations": [
        {
          "chunk_id": "CYH-000119312526059509-0295",
          "quote": "Income from operations\n11.9\n4.3\n7.7"
        },
        {
          "chunk_id": "CYH-000119312526059509-0295",
          "quote": "Impairment and gain (loss) on sale of businesses, net\n3.3\n(2.4\n)\n0.7"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "The lower debt balances reflected repayments of long-term indebtedness, while LTM capital expenditures of {{m:capex:LTM}} exceeded cash from operations of {{m:cfo:LTM}}, leaving FCF / debt slightly negative.",
      "citations": [
        {
          "chunk_id": "CYH-000119312526437869-0007",
          "quote": "Repayments of long-term indebtedness\n(2,151\n)\n(6,272\n)"
        }
      ]
    }
  ]
}

{
  "claims": [
    {
      "kind": "qualitative",
      "text": "The Company has a revolving asset-based loan facility with a maximum aggregate amount of $1.0 billion, subject to borrowing base capacity.",
      "citations": [
        {
          "chunk_id": "CYH-000119312526059509-0311",
          "quote": "The maximum aggregate amount under the ABL Facility is $1.0 billion, subject to borrowing base capacity"
